def check_perfect_square(n):
    """Check if a number is a perfect square"""

### Solution:

    if n < 0: 
        return False
    if n == 0 or n == 1: 
        return True

    left, right = 0, n // 2

    while left <= right:
        mid = (left + right) // 2
        if mid * mid == n: 
            return True
        elif mid * mid < n:
            left = mid + 1
        else:
            right = mid - 1

    return False

