    left = 0
    right = len(numbers) - 1

    while left <= right:
        mid = (left + right) // 2

        # Check if the value at mid is equal to the index at mid
        if numbers[mid] == mid:
            left = mid + 1
        else:
            right = mid - 1

    # Return the missing number
    return left

