public static int findSmallestGreaterOrEqual(int[] array, int target) {
    int n = array.length;
    int left = 0;
    int right = n - 1;

    while (left <= right) {
        int mid = (left + right) / 2;

        if (array[mid] >= target) {
            right = mid - 1;
        } else {
            left = mid + 1;
        }
    }

    if (left < n && array[left] >= target) {
        return left;
    } else {
        return -1;
    }
}
