class DoublyLinkedList {
private:
    struct Node {
        int data;
        Node* prev;
        Node* next;

        Node(int value) : data(value), prev(nullptr), next(nullptr) {}
    };

    Node* head;
    Node* tail;
    int size;

public:
    DoublyLinkedList() {
        head = new Node(0);
        tail = new Node(0);
        head->next = tail;
        tail->prev = head;
        size = 0;
    }

    ~DoublyLinkedList() {
        clear();
        delete head;
        delete tail;
    }

    void insertFront(int value) {
        Node* newNode = new Node(value);
        newNode->prev = head;
        newNode->next = head->next;
        head->next->prev = newNode;
        head->next = newNode;
        size++;
    }

    void insertEnd(int value) {
        Node* newNode = new Node(value);
        newNode->next = tail;
        newNode->prev = tail->prev;
        tail->prev->next = newNode;
        tail->prev = newNode;
        size++;
    }

    void deleteNode(int value) {
        Node* curr = head->next;
        while (curr != tail) {
            if (curr->data == value) {
                curr->prev->next = curr->next;
                curr->next->prev = curr->prev;
                delete curr;
                size--;
                return;
            }
            curr = curr->next;
        }
    }

    void reverse() {
        Node* curr = head;
        Node* temp = nullptr;
        while (curr != nullptr) {
            temp = curr->prev;
            curr->prev = curr->next;
            curr->next = temp;
            curr = curr->prev;
