```
public class BalancedBinarySearchTree {
    private Node root;

    private class Node {
        private int key;
        private Node left;
        private Node right;
        private int size;

        public Node(int key) {
            this.key = key;
            this.size = 1;
        }
    }

    public void insert(int key) {
        root = insert(root, key);
    }

    private Node insert(Node node, int key) {
        if (node == null) {
            return new Node(key);
        }

        if (key < node.key) {
            node.left = insert(node.left, key);
        } else if (key > node.key) {
            node.right = insert(node.right, key);
        }

        node.size = 1 + size(node.left) + size(node.right);
        return node;
    }

    public void delete(int key) {
        root = delete(root, key);
    }

    private Node delete(Node node, int key) {
        if (node == null) {
            return null;
        }

        if (key < node.key) {
            node.left = delete(node.left, key);
        } else if (key > node.key) {
            node.right = delete(node.right, key);
        } else {
            if (node.left == null) {
                return node.right;
            } else if (node.right == null) {
                return node.left;
            }

            Node temp = node;
            node = findMin(temp.right);
            node.right = deleteMin(temp.right);
            node.left = temp.left;
        }

        node.size = 1 + size(node.left) + size(node.right);
        return node;
    }

    private Node findMin(Node node) {
        if (node.left == null) {
            return node;
        }
        return findMin(node.left);
    }

    private Node deleteMin(Node node) {
        if (node.left == null) {
            return node.right;
        }
        node.left = deleteMin(node.left);
        node.size = 1 + size(node.left) + size(node.right);
        return node;
    }

    public int findKthSmallest(int k) {
        Node node = findKthSmallest(root, k);
        return node != null ? node.key : -1;
    }

    private Node findKthSmallest(Node node, int k) {
        if (node == null) {
            return null;
        }

        int leftSize = size(node.left);
        if (leftSize == k - 1) {
            return node;
        } else if (leftSize >= k) {
            return findKthSmallest(node.left, k);
        } else {
            return findKthSmallest(node.right, k - leftSize - 1);
        }
    }

    public int findLargest() {
        Node node = findLargest(root);
        return node != null ? node.key : -1;
    }

    private Node findLargest(Node node) {
        if (node == null) {
            return null;
        }

        if (node.right == null) {
            return node;
        }

        return findLargest(node.right);
    }

    public void merge(BalancedBinarySearchTree tree) {
        root = merge(root, tree.root);
    }

    private Node merge(Node node1, Node node2) {
        if (node1 == null) {
            return node2;
        }

        if (node2 == null) {
            return node1;
        }

        int totalSize = size(node1) + size(node2);
        if (Math.log(totalSize) / Math.log(2) <= Math.log(totalSize + 1) / Math.log(2)) {
            return mergeSmallHeight(node1, node2);
        } else {
            return mergeBalanced(node1, node2);
        }
    }

    private Node mergeSmallHeight(Node node1, Node node2) {
        if (node1 == null) {
            return node2;
        }

        if (node2 == null) {
            return node1;
        }

        if (Math.random() < (double) size(node1) / (size(node1) + size(node2))) {
            node1.right = mergeSmallHeight(node1.right, node2);
            node1.size = 1 + size(node1.left) + size(node1.right);
            return node1;
        } else {
            node2.left = mergeSmallHeight(node1, node2.left);
            node2.size = 1 + size(node2.left) + size(node2.right);
            return node2;
        }
    }

    private Node mergeBalanced(Node node1, Node node2) {
        int totalSize = size(node1) + size(node2);
        int mid = totalSize / 2;

        Node midNode = findKthSmallest(node1, mid + 1);
        midNode.left = merge(node1, null);
        midNode.right = merge(midNode.right, node2);
        midNode.size = size(midNode.left) + size(midNode.right) + 1;

        return midNode;
    }

    private int size(Node node) {
        return node != null ? node.size : 0;
    }
}
