```c
#include <stdio.h>

int binarySearch(int arr[], int target, int low, int high) {
    if (low <= high) {
        int mid = low + (high - low) / 2;

        // If the target is found, check if it is the first occurrence
        if (arr[mid] == target) {
            // Check if the element is the first occurrence
            if (mid == 0 || arr[mid - 1] != target) {
                return mid;
            } else {
                return binarySearch(arr, target, low, mid - 1);
            }
        }
        // If target is smaller than mid, it can only be present in left subarray
        else if (arr[mid] > target) {
            return binarySearch(arr, target, low, mid - 1);
        }
        // Else target can only be present in right subarray
        else {
            return binarySearch(arr, target, mid + 1, high);
        }
    }
    // Element not found, return the index where it would be inserted
    return low;
}

int main() {
    int arr[] = {1, 2, 2, 3, 4, 5, 5, 6, 7, 8};
    int target = 5;
    int n = sizeof(arr) / sizeof(arr[0]);

    int index = binarySearch(arr, target, 0, n - 1);

