Please make a C++ program that counts the number of unique elements in an array and prints the unique elements in ascending order. The array may contain negative integers as well.

int arr[] = {1, -2, 5, 3, -2, 6, 2, 3, 5};

Requirements:
- The program should have a time complexity of O(n log n), where n is the number of elements in the array.
- The program should have a space complexity of O(n), where n is the number of unique elements in the array.
- The program should not use any built-in functions or data structures for sorting or counting unique elements.
- The program should be implemented using only basic C++ syntax and constructs, without the use of advanced language features or libraries.
- The program should handle arrays with up to 10^6 elements.
- The program should handle arrays with both positive and negative integers.
- The program should handle duplicate elements in the array and only count them once.
- The program should handle an empty array and print an appropriate message.

Please note that the original test was already quite challenging, so I have kept the requirements the same.

### Response:
Here is an implementation of the program that meets all the requirements:

```cpp
#include <iostream>

void merge(int arr[], int left[], int right[], int leftSize, int rightSize) {
    int i = 0, j = 0, k = 0;

    while (i < leftSize && j < rightSize) {
        if (left[i] < right[j]) {
            arr[k++] = left[i++];
        } else if (left[i] > right[j]) {
            arr[k++] = right[j++];
        } else {
            i++;
            j++;
        }
    }

    while (i < leftSize) {
        arr[k++] = left[i++];
    }

    while (j < rightSize) {
        arr[k++] = right[j++];
    }
}

void mergeSort(int arr[], int size) {
    if (size <= 1) {
        return;
    }

    int mid = size / 2;
    int* left = new int[mid];
    int* right = new int[size - mid];

    for (int i = 0; i < mid; i++) {
        left[i] = arr[i];
    }

    for (int i = mid; i < size; i++) {
        right[i - mid] = arr[i];
    }

    mergeSort(left, mid);
    mergeSort(right, size - mid);
    merge(arr, left, right, mid, size - mid);

    delete[] left;
    delete[] right;
}

int countUniqueElements(int arr[], int size) {
    int count = 0;
    mergeSort(arr, size);

    for (int i = 0; i < size; i++) {
        if (arr[i] != arr[i + 1]) {
            count++;
        }
    }

    return count;
}

void printUniqueElements(int arr[], int size) {
    mergeSort(arr, size);
    int prev = arr[0];
    std::cout << prev << " ";

    for (int i = 1; i < size; i++) {
        if (arr[i] != prev) {
            std::cout << arr[i] << " ";
            prev = arr[i];
        }
    }

    std::cout << std::endl;
}

int main() {
    int arr[] = {1, -2, 5, 3, -2, 6, 2, 3, 5};
    int size = sizeof(arr) / sizeof(arr[0]);

    if (size == 0) {
        std::cout << "Array is empty" << std::endl;
        return 0;
    }

    int uniqueCount = countUniqueElements(arr, size);
    std::cout << "Number of unique elements: " << uniqueCount << std::endl;
    std::cout << "Unique elements in ascending order: ";
    printUniqueElements(arr, size);

    return 0;
}
```

This program uses the merge sort algorithm to sort the array in ascending order, which has a time complexity of O(n log n). The program then counts the number of unique elements by comparing adjacent elements in the sorted array. Finally, it prints the unique elements by iterating through the sorted array and skipping duplicate elements. The space complexity is O(n) because additional memory is used to store the left and right subarrays during the merge sort process.

