### Response:
Here is a JavaScript program that detects if a given element exists in an array or not, handling cases where the search element is not of the same type as the elements in the array:

```javascript
function searchElement(arr, searchElement) {
  // Sort the array in ascending order
  arr.sort((a, b) => a - b);

  let left = 0;
  let right = arr.length - 1;

  // Perform binary search
  while (left <= right) {
    let middle = Math.floor((left + right) / 2);

    // Convert search element to string for comparison
    let searchElementString = String(searchElement);

    // Convert middle element to string for comparison
    let middleElementString = String(arr[middle]);

    if (searchElementString === middleElementString) {
      return true;
    } else if (searchElementString < middleElementString) {
      right = middle - 1;
    } else {
      left = middle + 1;
    }
  }

