    for (int i = 0; i < rightSize; i++) {
        rightArr[i] = arr[mid + 1 + i];
    }

    // Merge the left and right subarrays back into the original array
    int i = 0, j = 0, k = low;
    while (i < leftSize && j < rightSize) {
        if (leftArr[i] <= rightArr[j]) {
            arr[k] = leftArr[i];
            i++;
        } else {
            arr[k] = rightArr[j];
            j++;
        }
        k++;
    }

    // Copy the remaining elements from the left subarray, if any
    while (i < leftSize) {
        arr[k] = leftArr[i];
        i++;
        k++;
    }

    // Copy the remaining elements from the right subarray, if any
    while (j < rightSize) {
        arr[k] = rightArr[j];
        j++;
        k++;
    }
}

// Function to perform merge sort on the array
void mergeSort(vector<int>& arr, int low, int high) {
    if (low < high) {
        int mid = low + (high - low) / 2;

        // Recursively divide the array into two halves and sort them
        mergeSort(arr, low, mid);
        mergeSort(arr, mid + 1, high);

        // Merge the sorted halves
        merge(arr, low, mid, high);
    }
}

int main() {
    int n;

    // Read the size of the array from the user
    cout << "Enter the size of the array: ";
    cin >> n;

    if (n <= 0 || n > 1e6) {
        cout << "Invalid size. Please enter a positive integer less than or equal to 10^6." << endl;
        return 0;
    }

    // Read the elements of the array from the user
    vector<int> arr(n);
    cout << "Enter the elements of the array: ";
    for (int i = 0; i < n; i++) {
        cin >> arr[i];
    }

    // Sort the array using merge sort
    mergeSort(arr, 0, n - 1);

    // Print the sorted array
    cout << "The sorted array is: ";
    for (int i = 0; i < n; i++) {
        cout << arr[i] << " ";
    }
    cout << endl;

    return 0;
}
```

This program uses the merge sort algorithm to sort the array. Merge sort has a time complexity of O(n log n), where n is the size of the array. The algorithm divides the array into two halves, recursively sorts the two halves, and then merges them back together to obtain the final sorted array. The merge operation is implemented in the `merge` function, while the merge sort algorithm is implemented in the `mergeSort` function.

The program first reads the size of the array from the user, checks if it is valid, and then reads the elements of the array. After sorting the array using merge sort, it prints the sorted array. Error handling is included to handle invalid input for the array size.

