### Response:
Here is the implementation of a function in Java that performs multiplication using only addition, subtraction, and bit shifting operations:

```java
public class Multiplication {
    public static int multiply(int a, int b) {
        int result = 0;
        boolean isNegative = false;

        if (a < 0 && b < 0) {
            a = negate(a);
            b = negate(b);
        } else if (a < 0 || b < 0) {
            isNegative = true;
            if (a < 0) {
                a = negate(a);
            } else {
                b = negate(b);
            }
        }

        while (b != 0) {
            if ((b & 1) == 1) {
                result = add(result, a);
            }
            a <<= 1;
            b >>= 1;
        }

        if (isNegative) {
            result = negate(result);
        }

        return result;
    }

    private static int add(int a, int b) {
        while (b != 0) {
            int carry = a & b;
            a ^= b;
            b = carry << 1;
        }

        return a;
    }

    private static int negate(int a) {
        return add(~a, 1);
    }

    public static void main(String[] args) {
        int a = 5;
        int b = -3;
        int result = multiply(a, b);
        System.out.println("Result: " + result);
    }
}
