        if (array[mid] == target) {
            // Handle duplicates
            while (mid > start && array[mid - 1] == target) {
                mid--;
            }
            return mid;
        }
        else if (array[mid] < target) {
            start = mid + 1;
        }
        else {
            end = mid - 1;
        }
    }
    return -1;
}

