    for (int i = 0; i < N; ++i) {
        a[i] = rand() % 2001 - 1000;
    }

    // Sort the vector in ascending order
    std::sort(a.begin(), a.end());

    // Generate a random target element between -1000 and 1000
    int target = rand() % 2001 - 1000;

    // Perform binary search
    int index = binarySearch(a, target);

    if (index != -1) {
        // Count the number of occurrences of the target element
        int count = 1;
        int left = index - 1;
        while (left >= 0 && a[left] == target) {
            count++;
            left--;
        }

        int right = index + 1;
        while (right < N && a[right] == target) {
            count++;
            right++;
        }

        std::cout << "The target element " << target << " is found at index " << index
                  << " with " << count << " occurrences." << std::endl;
    } else {
        std::cout << "The target element " << target << " is not found." << std::endl;
    }

    return 0;
}
