### Instruction:
Create a class in Java to store student grades with functions for adding and calculating average grades. The class should also include a function to find the highest and lowest grades in the list of student grades. The average grade should be calculated excluding the highest and lowest grades. The student grades should be stored in an array and the class should have a function to display the top 3 highest grades in descending order. Additionally, the class should implement a modified version of the merge sort algorithm to sort the grades in ascending order. The modified merge sort algorithm should have a time complexity of O(n log n). The class should also include a function to calculate the mode grade from the sorted list of grades. The mode grade is the grade that appears most frequently in the list. If there is more than one grade with the highest frequency, the mode should be the lowest grade among them.

### Response:
```java
import java.util.Arrays;

public class StudentGrades {
    private int[] grades;
    private int size;

    public StudentGrades(int maxSize) {
        grades = new int[maxSize];
        size = 0;
    }

    public void addGrade(int grade) {
        if (size < grades.length) {
            grades[size++] = grade;
        }
    }

    public double calculateAverage() {
        if (size == 0) {
            return 0;
        }

        int sum = 0;
        int maxGrade = grades[0];
        int minGrade = grades[0];

        for (int i = 0; i < size; i++) {
            sum += grades[i];

            if (grades[i] > maxGrade) {
                maxGrade = grades[i];
            }

            if (grades[i] < minGrade) {
                minGrade = grades[i];
            }
        }

        sum -= maxGrade + minGrade;
        return (double) sum / (size - 2);
    }

    public void displayTopThreeGrades() {
        int[] sortedGrades = Arrays.copyOf(grades, size);
        Arrays.sort(sortedGrades);

        System.out.println("Top 3 highest grades:");

        for (int i = size - 1; i >= Math.max(size - 3, 0); i--) {
            System.out.println(sortedGrades[i]);
        }
    }

    public void mergeSort() {
        mergeSortHelper(grades, 0, size - 1);
    }

    private void mergeSortHelper(int[] arr, int left, int right) {
        if (left < right) {
            int mid = (left + right) / 2;
            mergeSortHelper(arr, left, mid);
            mergeSortHelper(arr, mid + 1, right);
            merge(arr, left, mid, right);
        }
    }

    private void merge(int[] arr, int left, int mid, int right) {
        int leftSize = mid - left + 1;
        int rightSize = right - mid;

        int[] leftArr = new int[leftSize];
        int[] rightArr = new int[rightSize];

        for (int i = 0; i < leftSize; i++) {
            leftArr[i] = arr[left + i];
        }

        for (int j = 0; j < rightSize; j++) {
            rightArr[j] = arr[mid + 1 + j];
        }

        int i = 0, j = 0;
        int k = left;

        while (i < leftSize && j < rightSize) {
            if (leftArr[i] <= rightArr[j]) {
                arr[k++] = leftArr[i++];
            } else {
                arr[k++] = rightArr[j++];
            }
        }

        while (i < leftSize) {
            arr[k++] = leftArr[i++];
        }

        while (j < rightSize) {
            arr[k++] = rightArr[j++];
        }
    }

    public int calculateMode() {
        int[] sortedGrades = Arrays.copyOf(grades, size);
        Arrays.sort(sortedGrades);

        int currentGrade = sortedGrades[0];
        int currentCount = 1;

        int modeGrade = sortedGrades[0];
        int modeCount = 1;

        for (int i = 1; i < size; i++) {
            if (sortedGrades[i] == currentGrade) {
                currentCount++;
            } else {
                if (currentCount > modeCount || (currentCount == modeCount && sortedGrades[i] < modeGrade)) {
                    modeGrade = currentGrade;
                    modeCount = currentCount;
                }
                currentGrade = sortedGrades[i];
                currentCount = 1;
            }
        }

        return modeGrade;
    }

    public int getHighestGrade() {
        if (size == 0) {
            return 0;
        }

        int maxGrade = grades[0];

        for (int i = 1; i < size; i++) {
            if (grades[i] > maxGrade) {
                maxGrade = grades[i];
            }
        }

        return maxGrade;
    }

    public int getLowestGrade() {
        if (size == 0) {
            return 0;
        }

        int minGrade = grades[0];

