import java.util.ArrayList;
import java.util.List;

public class PalindromicWordsCounter {
    public static void main(String[] args) {
        String testString = "This is a test string with level 123@# palindromic words";

        List<Integer> positions = new ArrayList<>();

        int count = countPalindromicWords(testString, positions);

        System.out.println("Number of palindromic words found: " + count);
        System.out.println("Positions of palindromic words: " + positions);
        System.out.println("Number of non-palindromic words: " + (testString.split(" ").length - count));
    }

    public static int countPalindromicWords(String input, List<Integer> positions) {
        if (input == null || input.isEmpty()) {
            System.out.println("Error: Empty or null string");
            return 0;
        }

        String[] words = input.split(" ");
        int count = 0;

        for (int i = 0; i < words.length; i++) {
            String word = words[i].replaceAll("[^a-zA-Z0-9]", "").toLowerCase();
            if (isPalindromic(word)) {
                count++;
                positions.add(i);
            }
        }

        return count;
    }

    public static boolean isPalindromic(String word) {
        int left = 0;
        int right = word.length() - 1;

        while (left < right) {
            if (word.charAt(left) != word.charAt(right)) {
                return false;
            }
            left++;
            right--;
        }

        return true;
    }
}

