function sortEmployees(employees) {
  // Base case: if the array has only one or zero elements, return the array
  if (employees.length <= 1) {
    return employees;
  }

  // Find the middle index of the array
  const middleIndex = Math.floor(employees.length / 2);

  // Divide the array into two halves
  const leftHalf = employees.slice(0, middleIndex);
  const rightHalf = employees.slice(middleIndex);

  // Recursively sort the left and right halves
  const sortedLeft = sortEmployees(leftHalf);
  const sortedRight = sortEmployees(rightHalf);

  // Merge the sorted halves
  return merge(sortedLeft, sortedRight);
}

function merge(left, right) {
  let sorted = [];

  // While both left and right arrays are not empty
  while (left.length && right.length) {
    // Compare the ages of the first elements in the left and right arrays
    if (left[0].age < right[0].age) {
      // If the age of the first element in the left array is smaller,
      // add it to the sorted array
      sorted.push(left.shift());
    } else if (left[0].age > right[0].age) {
