Implement a custom sorting algorithm in C that has a time complexity of O(n log n) and sorts elements in descending order. Additionally, the algorithm should handle duplicate elements in the input array and maintain their relative order in the sorted output. However, you are not allowed to use any built-in sorting functions or libraries in your implementation. You must implement the entire sorting algorithm from scratch.

### Response:
Here is an implementation of the custom sorting algorithm in C that meets the given requirements:

```c
#include <stdio.h>
#include <stdlib.h>

void merge(int arr[], int left[], int leftSize, int right[], int rightSize) {
    int i = 0, j = 0, k = 0;

    while (i < leftSize && j < rightSize) {
        if (left[i] >= right[j]) {
            arr[k] = left[i];
            i++;
        }
        else {
            arr[k] = right[j];
            j++;
        }
        k++;
    }

    while (i < leftSize) {
        arr[k] = left[i];
        i++;
        k++;
    }

    while (j < rightSize) {
        arr[k] = right[j];
        j++;
        k++;
    }
}

void mergeSort(int arr[], int size) {
    if (size < 2) {
        return;
    }

    int mid = size / 2;
    int left[mid];
    int right[size - mid];

    for (int i = 0; i < mid; i++) {
        left[i] = arr[i];
    }

    for (int i = mid; i < size; i++) {
        right[i - mid] = arr[i];
    }

    mergeSort(left, mid);
    mergeSort(right, size - mid);
    merge(arr, left, mid, right, size - mid);
}

void customSort(int arr[], int size) {
    mergeSort(arr, size);
}

int main() {
